        interpretation_en="Saravali Ch. 35, v. 144-145 extols Pushkala Yoga: The Moon's dispositor and Lagna Lord are in Kendras or friendly signs, while benefics aspect Lagna. The native becomes a sovereign ruler, renowned, riding royal chariots, wealthy, and universally lauded.",
        interpretation_ta="சாராவளி அத்தியாயம் 35, சுலோகம் 144-145 புஷ்கல யோகத்தைப் போற்றுகிறது: சந்திரனின் அதிபதியும் லக்னாதிபதியும் கேந்திரத்தில் அமர்ந்து, லக்னத்தைச் சுபர்கள் பார்த்தால் அரசனுக்கு நிகரான வாழ்வு, சகல வாகன யோகம் மற்றும் நீங்காத புகழ் கிட்டும்.",
        astrological_principle_en="Pushkala Sovereign Auspiciousness Principle: Complete harmonization of physical self (Lagna) and emotional soul (Moon dispositor).",
        astrological_principle_ta="புஷ்கல யோக விதி: லக்னமும் சந்திர ராசி அதிபதியும் கேந்திர பலம் பெற்று சுபப் பார்வை பெறுவது அரச யோகத்தை உருவாக்கும்.",
