        interpretation_en="Saravali Ch. 34, v. 13: When natural benefics (Mercury, Jupiter, Venus) occupy the 6th, 7th, and 8th from Lagna without malefic conjunctions, Lagnadhi Yoga forms, bestowing scholarly leadership, virtuous character, wealth, and high office.",
        interpretation_ta="சாராவளி அத்தியாயம் 34, சுலோகம் 13: லக்னத்திற்கு 6, 7, 8 ஆகிய இடங்களில் இயற்கை சுபர்கள் அமர்வது லக்னாதி யோகம்; அறிவார்ந்த தலைமை, நற்பண்புகள், உயர் பதவி மற்றும் செல்வம் அருளும்.",
