        interpretation_en="Saravali Ch. 35, v. 14: Mutual reception or conjunction of 9th and 10th lords in auspicious houses forms the paramount Dharma-Karmadhipati Raja Yoga, conferring emperor-like status, righteous rule, and enduring prosperity.",
        interpretation_ta="சாராவளி அத்தியாயம் 35, சுலோகம் 14: 9 மற்றும் 10-ஆம் அதிபதிகள் பரிவர்த்தனை பெற்றாலோ அல்லது இணைந்தாலோ தர்ம-கர்மாதிபதி ராஜயோகம் உண்டாகும்; மாபெரும் சக்கரவர்த்தி யோகம், தர்ம ஆட்சி மற்றும் அழியாத செல்வம் கிட்டும்.",
