        condition_tree={'condition_type': 'planet_sign', 'planet': 'Sun', 'sign': 7, 'chart': 'd1'},
        interpretation_en="Saravali Ch. 39, v. 1: If the Sun is at deep fall in Libra (Param Neecha around 10°), it destroys hundreds of potential Raja Yogas in the nativity, rendering royal status ineffective.",
        interpretation_ta="சாராவளி அத்தியாயம் 39, சுலோகம் 1: சூரிய பகவான் துலாம் ராசியில் பரம நீசம் பெற்றால், ஜாதகத்தில் உள்ள நூற்றுக்கணக்கான ராஜயோகங்களையும் அது அழித்துவிடும் என்று சாராவளி எச்சரிக்கிறது.",
        astrological_principle_en="Solar Debility Sovereign Nullification Principle.",
